  '- CONFERÊNCIA: a soma de valor_brl deve ser igual a total_fatura.',
  'Formato:',
  '{"vencimento":"AAAA-MM-DD","data_fechamento":"","total_fatura":0,"pagamento_fatura_anterior":0,"lancamentos":[{"data":"DD/MM","descricao":"","valor_brl":0,"parcela":"","final_cartao":"","titular":"","tipo":"compra"}]}'
].join('\n');
return { json: { contaCartaoId: 00000000000, contaCartaoNome: 'CARTÃO DE CRÉDITO CAIXA REDACTED', arquivo: bin[key].fileName || 'fatura.pdf', prompt, pdf_b64: buf.toString('base64') } };

const raw = ($json.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
if (!raw.trim()) throw new Error('A IA não devolveu nada para esta fatura.');
let f; try { f = JSON.parse(raw); } catch (e) { f = JSON.parse(raw.replace(/^\s*```(json)?/i, '').replace(/```\s*$/, '').trim()); }
const cfg = $('Config + PDF').item.json;
const venc = String(f.vencimento || '').slice(0, 10);
