const vy = Number(venc.slice(0, 4));
const MESES = { jan: 1, fev: 2, mar: 3, abr: 4, mai: 5, jun: 6, jul: 7, ago: 8, set: 9, out: 10, nov: 11, dez: 12 };
const toISO = txt => {
  const s = String(txt || '').trim().toLowerCase();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/); if (m) return m[0];
  m = s.match(/^(\d{1,2})\s*[\/\-. ]\s*([a-zç]{3,}|\d{1,2})(?:\s*[\/\-. ]\s*(\d{2,4}))?$/);
  if (!m) return '';
  const mesN = /\d/.test(m[2]) ? Number(m[2]) : MESES[m[2].slice(0, 3)];
  if (!mesN || mesN > 12) return '';
  const d = m[1].padStart(2, '0'), mo = String(mesN).padStart(2, '0');
