  const descricao = String(l.descricao || '').trim();
  const pm = String(l.parcela || '').match(/(\d{1,2})\s*\/\s*(\d{1,2})/) || descricao.match(/(\d{1,2})\s*(?:DE|\/)\s*(\d{1,2})\s*$/i);
  const tipo = String(l.tipo || 'compra').toLowerCase();
  const valor = r2(l.valor_brl);
  const credito = valor < 0;
  const tarifa = !credito && (['anuidade', 'tarifa', 'iof', 'juros'].includes(tipo) || /ANUIDADE|TARIFA|\bIOF\b|JUROS|ENCARGO/i.test(descricao));
  return { n: i + 1, dataFatura: toISO(l.data), descricao, valor, parcelaAtual: pm ? Number(pm[1]) : null, parcelaTotal: pm ? Number(pm[2]) : null,
    final: String(l.final_cartao || '').replace(/\D/g, '').slice(-4), tipo, tarifa, credito, parcelada: !!pm && !credito };
});
// Data de fechamento: a impressa na fatura; se não tiver, a data da última compra à vista (padrão da Redacted: parcelas e anuidade nessa data)
const avista = linhas.filter(l => !l.parcelada && !l.tarifa && !l.credito && l.dataFatura && l.dataFatura <= venc).map(l => l.dataFatura).sort();
const fech = /^\d{4}-\d{2}-\d{2}$/.test(String(f.data_fechamento || '')) ? f.data_fechamento : (avista[avista.length - 1] || '');
