const F = $('Organizar linhas + data do lançamento').first().json;
const ext = $('Omie - extrato do cartão (só leitura)').first().json;
const cats = {}, forn = {};
$('Omie - categorias').all().forEach(i => (i.json.categoria_cadastro || []).forEach(c => { cats[c.codigo] = c.descricao; }));
$('Omie - fornecedores').all().forEach(i => (i.json.clientes_cadastro_resumido || []).forEach(c => { forn[c.codigo_cliente] = { cod: c.codigo_cliente, nome: c.nome_fantasia || c.razao_social || '', razao: c.razao_social || '', fantasia: c.nome_fantasia || '' }; }));
const toISO = d => { const m = String(d || '').match(/(\d{2})\/(\d{2})\/(\d{4})/); return m ? m[3] + '-' + m[2] + '-' + m[1] : ''; };
const addDays = (iso, n) => { const d = new Date(iso + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const cents = v => Math.round(Number(v) * 100);
const br = iso => iso ? iso.split('-').reverse().join('/') : '';
const brl = v => Number(v || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[^A-Z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const extratoOk = !ext.faultstring && Array.isArray(ext.listaMovimentos);
const movs = (ext.listaMovimentos || []).filter(m => Number(m.nValorDocumento) !== 0 && /Conta Corrente/i.test(m.cOrigem || '')).map(m => ({
  id: m.nCodLancamento, data: toISO(m.dDataLancamento), valor: Number(m.nValorDocumento), cli: m.nCodCliente, cliNome: m.cRazCliente || m.cDesCliente || '', cat: m.cCodCategoria, catNome: m.cDesCategoria || '', obs: m.cObservacoes || '', usado: false }));
const datas = F.linhas.map(l => l.dataLanc).filter(Boolean).sort();
const de = addDays(datas[0] || addDays(F.vencimento, -45), -3), ate = addDays(F.vencimento, 3);
const daFatura = movs.filter(m => m.data >= de && m.data <= ate);
const historico = movs.filter(m => m.data < de);
const todos = historico.concat(daFatura);
const linhas = F.linhas.map(l => ({ ...l, status: '', mov: null }));
const alvo = l => -cents(l.valor);
const dist = (a, b) => Math.abs((new Date(a) - new Date(b)) / 86400000);
[0, 1].forEach(passo => {
  linhas.filter(l => !l.mov).forEach(l => {
    let best = null, bd = 999;
    for (const m of daFatura) {
      if (m.usado || cents(m.valor) !== alvo(l)) continue;
      const d = l.dataLanc ? dist(m.data, l.dataLanc) : 500;
      if (passo === 0 && d > 2) continue;
      if (d < bd) { best = m; bd = d; }
    }
    if (best) { best.usado = true; l.mov = best; l.status = 'OK'; }
  });
});
linhas.forEach(l => { if (!l.mov) l.status = 'FALTA'; });
const PREF = new Set(['JIM', 'MP', 'ZP', 'IG', 'PG', 'PAG', 'EC', 'SUMUP', 'TON', 'STONE', 'PAGSEGURO', 'PICPAY', 'WWW', 'DL', 'EBN', 'PP', 'PAYGO']);
const STOP = new Set(['LTDA', 'EPP', 'EIRELI', 'DOS', 'DAS', 'COM', 'BRASIL', 'COMERCIO', 'SERVICOS', 'LOJA', 'EMPRESA', 'PAGAMENTOS', 'COMERCIAL', 'INDUSTRIA', 'BRA', 'BILL', 'PARC']);
const limpa = s => norm(s).replace(/\b\d{1,2} (DE )?\d{1,2}\b/g, ' ');
const toks = s => limpa(s).split(' ').filter(t => t.length >= 3 && !STOP.has(t) && !PREF.has(t) && !/\d/.test(t));
const fornIdx = Object.values(forn).map(f => ({ ...f, toks: new Set(toks(f.razao + ' ' + f.fantasia)), compact: limpa(f.razao + ' ' + f.fantasia).replace(/ /g, '') }));
const usados = {}; todos.forEach(m => { usados[m.cli] = (usados[m.cli] || 0) + 1; });
const catDoForn = cli => { const c = {}; todos.filter(m => m.cli === cli && m.cat).forEach(m => { c[m.cat] = (c[m.cat] || 0) + 1; }); const e = Object.entries(c).sort((a, b) => b[1] - a[1])[0]; return e ? e[0] : ''; };
const pelaObs = l => {
  const tk = toks(l.descricao); if (!tk.length) return null;
  const cand = todos.filter(m => (m.valor < 0) === !l.credito && (toks(m.obs).includes(tk[0]) || toks(m.cliNome).includes(tk[0])));
  if (!cand.length) return null;
  const cont = {}; cand.forEach(m => { cont[m.cli] = (cont[m.cli] || 0) + 1; });
  const cli = Number(Object.entries(cont).sort((a, b) => b[1] - a[1])[0][0]);
  return { cod: cli, nome: (cand.find(m => m.cli === cli) || {}).cliNome, como: 'histórico do extrato' };
};
const peloNome = l => {
  const tk = toks(l.descricao); if (!tk.length) return null;
  const peso = tk.reduce((s, t) => s + t.length, 0); let best = null;
  for (const f of fornIdx) {
    let sc = 0, primeiro = false;
    tk.forEach((t, k) => { if (f.toks.has(t) || (t.length >= 5 && f.compact.includes(t))) { sc += t.length; if (k === 0) primeiro = true; } });
    if (!sc || !primeiro) continue; sc = sc / peso + (usados[f.cod] ? 0.15 : 0);
    if (!best || sc > best.sc) best = { f, sc };
  }
  return best && best.sc >= 0.5 ? { cod: best.f.cod, nome: best.f.nome, como: 'cadastro do Omie' } : null;
};
const especial = l => {
  const re = l.credito ? /CASHBACK|AJUSTE|CREDITO|ESTORNO/ : /ANUIDADE|TARIFA|IOF|JUROS/;
  const m = todos.filter(x => (x.valor > 0) === l.credito && re.test(norm(x.obs + ' ' + x.catNome))).sort((a, b) => (a.data < b.data ? 1 : -1))[0];
  return m ? { cod: m.cli, nome: m.cliNome, cat: m.cat, como: 'igual ao último lançamento da Redacted' } : null;
