const REGRAS = [[/APPLE|CANVA|GOOGLE|MICROSOFT|ADOBE|OPENAI|ANTHROPIC|ZOOM|MELI/, /SISTEMAS E APLICATIVOS/], [/PAPELAR|COPIADORA|KALUNGA/, /MATERIAL DE ESCRITORIO/], [/MERCADO|SUPERM|EMPORIO|PAO DE ACUCAR|EXTRA/, /MERCADO/], [/CAFE|BOLO|PADARIA|LANCH|RESTAUR|DOCE/, /REFEICOES|LANCHE/]];
const catList = Object.entries(cats).map(([codigo, descricao]) => ({ codigo, descricao }));
