const catOutras = catList.find(c => /OUTRAS DESPESAS/.test(norm(c.descricao)));
const hash = s => { let h = 5381; for (const ch of s) h = ((h * 33) ^ ch.charCodeAt(0)) >>> 0; return h.toString(36).toUpperCase(); };
