  return { n: l.n, descricao: l.descricao, valor: l.valor, dataLanc: l.dataLanc, regraData: l.regraData, credito: l.credito,
    fornCod: fo ? fo.cod : null, fornNome: fo ? fo.nome : nomeNovo(l.descricao), fornOrigem: fo ? fo.como : 'NOVO (cadastrar)', catCod: cat, catNome: cats[cat] || cat, catOrigem,
    omie: { cCodIntLanc: ('CX' + hash(F.contaCartaoId + '|' + F.vencimento + '|' + l.n + '|' + cents(l.valor) + '|' + norm(l.descricao))).slice(0, 18),
      cabecalho: { nCodCC: F.contaCartaoId, dDtLanc: br(l.dataLanc), nValorLanc: Math.abs(l.valor) },
      detalhes: { cCodCateg: cat, cTipo: '99999', cObs: (l.descricao + parc + ' | Lançado automaticamente pelo robô (fatura venc. ' + br(F.vencimento) + ')').slice(0, 500) },
      diversos: { cNatureza: l.credito ? 'R' : 'P' } } };
});
const r = { vencimento: F.vencimento, fechamento: F.fechamento, totalFatura: F.totalFatura, somaLinhas: F.somaLinhas, leituraIA_ok: cents(F.somaLinhas) === cents(F.totalFatura), extratoOk,
  linhasFatura: linhas.length, ok: linhas.filter(l => l.status === 'OK').length, falta: aLancar.length, valorFalta: Math.round(aLancar.reduce((s, a) => s + a.valor, 0) * 100) / 100,
  semData: aLancar.filter(a => !/^\d{4}-\d{2}-\d{2}$/.test(a.dataLanc || '')).length, fornNovos: aLancar.filter(a => !a.fornCod).length, movsJanela: daFatura.length };
r.fechou = r.falta === 0;
const td = 'style="padding:4px 6px;border-bottom:1px solid #ddd;font-size:12px;vertical-align:top"', tdr = 'style="padding:4px 6px;border-bottom:1px solid #ddd;font-size:12px;text-align:right;white-space:nowrap"', th = 'style="padding:4px 6px;border-bottom:2px solid #333;font-size:12px;text-align:left"';
const card = (t, v, cor) => '<div style="display:inline-block;margin:4px;padding:8px 12px;border:1px solid #ccc;border-radius:6px;min-width:120px"><div style="font-size:11px;color:#555">' + t + '</div><div style="font-size:18px;font-weight:bold;color:' + (cor || '#222') + '">' + v + '</div></div>';
let h = '<div style="font-family:Arial,sans-serif;text-align:left;max-width:1100px;margin:auto"><h2 style="margin:4px 0">Redacted Redacted — CARTÃO CAIXA — fatura venc. ' + br(F.vencimento) + '</h2>';
h += '<p style="font-size:13px">' + (!extratoOk ? '<b style="color:#c0392b">⚠️ Não consegui ler o extrato do Omie. Rode de novo.</b>' : r.fechou ? '<b style="color:#1b7f3b">✅ Fatura FECHADA: tudo o que está na fatura já está no extrato do Omie.</b>' : '<b style="color:#c0392b">⚠️ ' + r.falta + ' linha(s) da fatura não estão no extrato.</b>') + '</p>';
