  const motivo = !r.leituraIA_ok ? 'a soma lida pela IA não bate com o total da fatura.' : !r.extratoOk ? 'o Omie não devolveu o extrato — rode de novo.' : r.semData ? 'a IA não leu a data de ' + r.semData + ' linha(s) — rode de novo.' : 'não há nada faltando no extrato.';
